package com.thorium.preview.game;

import android.opengl.GLES20;
import android.opengl.GLES30;
import android.util.Log;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Learned phase-centred motion estimation (our own trained network; its
 * structure follows the REA study of Lossless Scaling's frame generation,
 * methods only). Shaders and weights come from {@link LearnedFrameShaders},
 * generated by tools/learned_framegen/export_gles.py; the pass order here is
 * the one tools/learned_framegen/verify_gles.py checks against PyTorch.
 *
 * Per real frame: the history image is box-filtered to the analysis size
 * (native up to 640 wide, a half up to 1280, else a quarter, as in training),
 * a 2x2-mean pyramid is built and one shared encoder writes 16 feature
 * channels per level into the frame's slot. Per generated phase: coarse to
 * fine, a correlation pass and two four-layer heads update two fields; a
 * visibility branch accumulates four logits on the three finest levels. The
 * output pass blends four motion-compensated samples of the full-resolution
 * history by softmax(logits) times the phase weights.
 *
 * All methods run on the GL thread of the owning generator.
 */
final class LearnedFrameEstimator {
    private static final String TAG = "EmuFusionLearnedFG";
    static final int LEVELS = 5;
    static final int DELTA_LEVELS = 3;
    static final int SLOTS = 2;

    private int historyWidth, historyHeight;
    private int analysisWidth, analysisHeight, divisor;
    private final int[][] mipSize = new int[LEVELS][2];
    private final int[][] halfSize = new int[LEVELS][2];
    private final int[][] qSize = new int[LEVELS][2];

    // Programs.
    private int resample2, resample4, mip, enc0, enc1, enc2, enc3, corr;
    private final int[] headC1 = new int[2], headC2 = new int[2], headC3 = new int[2], headOut = new int[2];
    private int vis0, vis1, vis2, vis3, visOut, generate;
    private final Map<Integer, Map<String, Integer>> uniforms = new HashMap<>();

    // Textures.
    private final int[] mips = new int[LEVELS];
    private final int[][] e0 = new int[LEVELS][2], e1 = new int[LEVELS][2], e2 = new int[LEVELS][4];
    private final int[][][] features = new int[SLOTS][LEVELS][4];
    private final int[][] corrTex = new int[LEVELS][3];
    private final int[][] scratchH = new int[LEVELS][4], scratchG = new int[LEVELS][4];
    private final int[] field1 = new int[LEVELS], field2 = new int[DELTA_LEVELS];
    private final int[][] visV = new int[DELTA_LEVELS][2], visU = new int[DELTA_LEVELS][2];
    private final int[] logits = new int[DELTA_LEVELS];
    private int zeroField;
    private int framebuffer;
    private int attached;
    private final Set<String> verifiedTargets = new HashSet<>();
    private final long[] slotKey = new long[SLOTS];
    private boolean ready;
    private boolean failed;
    private final int[] savedFramebuffer = new int[1];
    private final int[] savedViewport = new int[4];

    long encodes, estimates, generates;

    boolean failed() { return failed; }

    /** (Re)allocates for a history size; false when this device cannot run the estimator. */
    boolean ensure(int width, int height) {
        if (failed) return false;
        if (ready && width == historyWidth && height == historyHeight) return true;
        try {
            if (generate == 0) compilePrograms();
            releaseTextures();
            historyWidth = width;
            historyHeight = height;
            divisor = width > 1280 ? 4 : width > 640 ? 2 : 1;
            analysisWidth = Math.max(1, width / divisor);
            analysisHeight = Math.max(1, height / divisor);
            allocate();
            ready = true;
            Log.i(TAG, "Learned estimator allocated history=" + width + "x" + height +
                    " analysis=" + analysisWidth + "x" + analysisHeight +
                    " q0=" + qSize[0][0] + "x" + qSize[0][1]);
            return true;
        } catch (RuntimeException failure) {
            Log.w(TAG, "Learned estimator unavailable", failure);
            failed = true;
            release();
            return false;
        }
    }

    /** True when the slot already holds features for this frame key. */
    boolean holds(int slot, long key) { return key != 0L && slotKey[slot] == key; }

    void forget() { slotKey[0] = slotKey[1] = 0L; }

    /** Swaps the two feature slots (the right frame of one pair is the left of the next). */
    void swapSlots() {
        int[][] t = features[0]; features[0] = features[1]; features[1] = t;
        long k = slotKey[0]; slotKey[0] = slotKey[1]; slotKey[1] = k;
    }

    /** Per-real-frame work: features of one history image into a slot. */
    void encode(int slot, int historyTexture, long key) {
        saveState();
        try {
            if (divisor == 1) {
                encodeLevels(slot, historyTexture, historyWidth, historyHeight);
            } else {
                int program = divisor == 4 ? resample4 : resample2;
                begin(program, analysisWidth, analysisHeight, mips[0]);
                bind(program, "uIn0", historyTexture, 0);
                GLES20.glUniform2f(location(program, "uTexel"), 1f / historyWidth, 1f / historyHeight);
                GLES30.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
                encodeLevels(slot, mips[0], analysisWidth, analysisHeight);
            }
            slotKey[slot] = key;
            ++encodes;
        } finally {
            restoreState();
        }
    }

    private void encodeLevels(int slot, int level0, int width0, int height0) {
        for (int k = 0; k < LEVELS; ++k) {
            int source = k == 0 ? level0 : mips[k];
            int sw = mipSize[k][0], sh = mipSize[k][1];
            if (k > 0) {
                begin(mip, mipSize[k][0], mipSize[k][1], mips[k]);
                bind(mip, "uIn0", k == 1 ? level0 : mips[k - 1], 0);
                sizes(mip, mipSize[k - 1][0], mipSize[k - 1][1], sw, sh);
                GLES30.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
            }
            int hw = halfSize[k][0], hh = halfSize[k][1], qw = qSize[k][0], qh = qSize[k][1];
            begin(enc0, hw, hh, e0[k]);
            bind(enc0, "uIn0", source, 0);
            sizes(enc0, sw, sh, hw, hh);
            GLES30.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
            conv(enc1, e0[k], e1[k], hw, hh, hw, hh);
            conv(enc2, e1[k], e2[k], hw, hh, qw, qh);
            conv(enc3, e2[k], features[slot][k], qw, qh, qw, qh);
        }
    }

    /** Per-phase work: fields and logits for phase t between slot 0 (A) and slot 1 (B). */
    void estimate(float t) {
        saveState();
        try {
            for (int k = LEVELS - 1; k >= 0; --k) {
                int qw = qSize[k][0], qh = qSize[k][1];
                boolean hasCoarse = k + 1 < LEVELS;
                int coarse = hasCoarse ? field1[k + 1] : zeroField;
                begin(corr, qw, qh, corrTex[k]);
                bindFeatures(corr, k, 0);
                bind(corr, "uCoarse", coarse, 8);
                GLES20.glUniform1f(location(corr, "uHasCoarse"), hasCoarse ? 1f : 0f);
                GLES20.glUniform1f(location(corr, "uT"), t);
                GLES30.glUniform2i(location(corr, "uOut"), qw, qh);
                GLES30.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
                for (int head = 0; head < (k < DELTA_LEVELS ? 2 : 1); ++head) {
                    conv(headC1[head], corrTex[k], scratchH[k], qw, qh, qw, qh);
                    conv(headC2[head], scratchH[k], scratchG[k], qw, qh, qw, qh);
                    conv(headC3[head], scratchG[k], scratchH[k], qw, qh, qw, qh);
                    int out = head == 0 ? field1[k] : field2[k];
                    int program = headOut[head];
                    begin(program, qw, qh, out);
                    for (int i = 0; i < 4; ++i) bind(program, "uIn" + i, scratchH[k][i], i);
                    bind(program, "uCoarse", coarse, 4);
                    GLES20.glUniform1f(location(program, "uHasCoarse"), hasCoarse ? 1f : 0f);
                    sizes(program, qw, qh, qw, qh);
                    GLES30.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
                }
                if (k < DELTA_LEVELS) {
                    int low2 = k + 1 < DELTA_LEVELS ? field2[k + 1] : coarse;
                    begin(vis0, qw, qh, visV[k]);
                    bindFeatures(vis0, k, 0);
                    bind(vis0, "uLow1", coarse, 8);
                    bind(vis0, "uLow2", low2, 9);
                    GLES20.glUniform1f(location(vis0, "uT"), t);
                    GLES30.glUniform2i(location(vis0, "uOut"), qw, qh);
                    GLES30.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
                    conv(vis1, visV[k], visU[k], qw, qh, qw, qh);
                    conv(vis2, visU[k], visV[k], qw, qh, qw, qh);
                    conv(vis3, visV[k], visU[k], qw, qh, qw, qh);
                    boolean hasPrev = k + 1 < DELTA_LEVELS;
                    begin(visOut, qw, qh, logits[k]);
                    bind(visOut, "uIn0", visU[k][0], 0);
                    bind(visOut, "uIn1", visU[k][1], 1);
                    bind(visOut, "uPrev", hasPrev ? logits[k + 1] : zeroField, 2);
                    GLES20.glUniform1f(location(visOut, "uHasPrev"), hasPrev ? 1f : 0f);
                    sizes(visOut, qw, qh, qw, qh);
                    GLES30.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
                }
            }
            ++estimates;
        } finally {
            restoreState();
        }
    }

    /** Output pass into the caller's framebuffer and viewport, on the caller's quad. */
    int generateProgram() { return generate; }

    void bindGenerate(int frameA, int frameB, float t) {
        GLES20.glUseProgram(generate);
        bind(generate, "uFrameA", frameA, 0);
        bind(generate, "uFrameB", frameB, 1);
        bind(generate, "uF1", field1[0], 2);
        bind(generate, "uF2", field2[0], 3);
        bind(generate, "uW", logits[0], 4);
        GLES20.glUniform1f(location(generate, "uT"), t);
        GLES20.glUniform2f(location(generate, "uQ0"), qSize[0][0], qSize[0][1]);
        ++generates;
    }

    // --- passes ---------------------------------------------------------------

    private void conv(int program, int[] inputs, int[] outputs, int inW, int inH, int outW, int outH) {
        begin(program, outW, outH, outputs);
        for (int i = 0; i < inputs.length; ++i) bind(program, "uIn" + i, inputs[i], i);
        sizes(program, inW, inH, outW, outH);
        GLES30.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
    }

    private void bindFeatures(int program, int k, int firstUnit) {
        for (int i = 0; i < 4; ++i) {
            bind(program, "uA" + i, features[0][k][i], firstUnit + i);
            bind(program, "uB" + i, features[1][k][i], firstUnit + 4 + i);
        }
    }

    private void sizes(int program, int inW, int inH, int outW, int outH) {
        int in = location(program, "uIn");
        if (in >= 0) GLES30.glUniform2i(in, inW, inH);
        GLES30.glUniform2i(location(program, "uOut"), outW, outH);
    }

    private void begin(int program, int width, int height, int... targets) {
        GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER, framebuffer);
        for (int i = 0; i < targets.length; ++i)
            GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER, GLES30.GL_COLOR_ATTACHMENT0 + i,
                    GLES20.GL_TEXTURE_2D, targets[i], 0);
        // ES 3.0 renders the intersection of all attachments: detach stale ones.
        for (int i = targets.length; i < attached; ++i)
            GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER, GLES30.GL_COLOR_ATTACHMENT0 + i,
                    GLES20.GL_TEXTURE_2D, 0, 0);
        attached = targets.length;
        GLES30.glDrawBuffers(targets.length, DRAW_BUFFERS[targets.length], 0);
        String key = java.util.Arrays.toString(targets);
        if (verifiedTargets.add(key) && GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER) !=
                GLES20.GL_FRAMEBUFFER_COMPLETE)
            throw new IllegalStateException("learned estimator framebuffer incomplete " + key);
        GLES20.glViewport(0, 0, width, height);
        GLES20.glUseProgram(program);
    }

    private static final int[][] DRAW_BUFFERS = {
            {},
            {GLES30.GL_COLOR_ATTACHMENT0},
            {GLES30.GL_COLOR_ATTACHMENT0, GLES30.GL_COLOR_ATTACHMENT1},
            {GLES30.GL_COLOR_ATTACHMENT0, GLES30.GL_COLOR_ATTACHMENT1, GLES30.GL_COLOR_ATTACHMENT2},
            {GLES30.GL_COLOR_ATTACHMENT0, GLES30.GL_COLOR_ATTACHMENT1, GLES30.GL_COLOR_ATTACHMENT2,
                    GLES30.GL_COLOR_ATTACHMENT3},
    };

    private void bind(int program, String name, int texture, int unit) {
        GLES20.glActiveTexture(GLES20.GL_TEXTURE0 + unit);
        GLES20.glBindTexture(GLES20.GL_TEXTURE_2D, texture);
        GLES20.glUniform1i(location(program, name), unit);
    }

    private int location(int program, String name) {
        Map<String, Integer> cache = uniforms.get(program);
        if (cache == null) uniforms.put(program, cache = new HashMap<>());
        Integer value = cache.get(name);
        if (value == null) cache.put(name, value = GLES20.glGetUniformLocation(program, name));
        return value;
    }

    private void saveState() {
        GLES20.glGetIntegerv(GLES20.GL_FRAMEBUFFER_BINDING, savedFramebuffer, 0);
        GLES20.glGetIntegerv(GLES20.GL_VIEWPORT, savedViewport, 0);
    }

    private void restoreState() {
        // Leave this estimator's framebuffer with one attachment so the
        // caller's later draws never see stale multi-target state.
        GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER, framebuffer);
        for (int i = 1; i < attached; ++i)
            GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER, GLES30.GL_COLOR_ATTACHMENT0 + i,
                    GLES20.GL_TEXTURE_2D, 0, 0);
        attached = Math.min(attached, 1);
        GLES30.glDrawBuffers(1, DRAW_BUFFERS[1], 0);
        GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER, savedFramebuffer[0]);
        GLES20.glViewport(savedViewport[0], savedViewport[1], savedViewport[2], savedViewport[3]);
        GLES20.glActiveTexture(GLES20.GL_TEXTURE0);
    }

    // --- resources ------------------------------------------------------------

    private static final String RESAMPLE_2 =
            "#version 300 es\nprecision highp float;\nuniform sampler2D uIn0;uniform vec2 uTexel;\n" +
            "layout(location=0) out vec4 o0;\n" +
            // One bilinear tap at the shared corner of a 2x2 block is its exact mean.
            "void main(){vec2 c=gl_FragCoord.xy*2.0*uTexel;o0=texture(uIn0,c);}\n";
    private static final String RESAMPLE_4 =
            "#version 300 es\nprecision highp float;\nuniform sampler2D uIn0;uniform vec2 uTexel;\n" +
            "layout(location=0) out vec4 o0;\n" +
            // Four bilinear taps at +-1 texel around a 4x4 block's centre: its exact mean.
            "void main(){vec2 c=gl_FragCoord.xy*4.0*uTexel;\n" +
            " o0=0.25*(texture(uIn0,c+vec2(-uTexel.x,-uTexel.y))+texture(uIn0,c+vec2(uTexel.x,-uTexel.y))+\n" +
            "  texture(uIn0,c+vec2(-uTexel.x,uTexel.y))+texture(uIn0,c+vec2(uTexel.x,uTexel.y)));}\n";

    private void compilePrograms() {
        String v = LearnedFrameShaders.VERTEX;
        resample2 = link(v, RESAMPLE_2);
        resample4 = link(v, RESAMPLE_4);
        mip = link(v, LearnedFrameShaders.MIP);
        enc0 = link(v, LearnedFrameShaders.ENC0);
        enc1 = link(v, LearnedFrameShaders.ENC1);
        enc2 = link(v, LearnedFrameShaders.ENC2);
        enc3 = link(v, LearnedFrameShaders.ENC3);
        corr = link(v, LearnedFrameShaders.CORR);
        headC1[0] = link(v, LearnedFrameShaders.H1C1);
        headC2[0] = link(v, LearnedFrameShaders.H1C2);
        headC3[0] = link(v, LearnedFrameShaders.H1C3);
        headOut[0] = link(v, LearnedFrameShaders.H1OUT);
        headC1[1] = link(v, LearnedFrameShaders.H2C1);
        headC2[1] = link(v, LearnedFrameShaders.H2C2);
        headC3[1] = link(v, LearnedFrameShaders.H2C3);
        headOut[1] = link(v, LearnedFrameShaders.H2OUT);
        vis0 = link(v, LearnedFrameShaders.VIS0);
        vis1 = link(v, LearnedFrameShaders.VIS1);
        vis2 = link(v, LearnedFrameShaders.VIS2);
        vis3 = link(v, LearnedFrameShaders.VIS3);
        visOut = link(v, LearnedFrameShaders.VISOUT);
        generate = link(LearnedFrameShaders.VERTEX_QUAD, LearnedFrameShaders.GENERATE);
        int[] ids = new int[1];
        GLES20.glGenFramebuffers(1, ids, 0);
        framebuffer = ids[0];
    }

    private static int link(String vertex, String fragment) {
        int vs = compile(GLES20.GL_VERTEX_SHADER, vertex);
        int fs = compile(GLES20.GL_FRAGMENT_SHADER, fragment);
        int program = GLES20.glCreateProgram();
        GLES20.glAttachShader(program, vs);
        GLES20.glAttachShader(program, fs);
        GLES20.glLinkProgram(program);
        GLES20.glDeleteShader(vs);
        GLES20.glDeleteShader(fs);
        int[] ok = new int[1];
        GLES20.glGetProgramiv(program, GLES20.GL_LINK_STATUS, ok, 0);
        if (ok[0] == 0) {
            String log = GLES20.glGetProgramInfoLog(program);
            GLES20.glDeleteProgram(program);
            throw new IllegalStateException("learned program link failed: " + log);
        }
        return program;
    }

    private static int compile(int type, String source) {
        int shader = GLES20.glCreateShader(type);
        GLES20.glShaderSource(shader, source);
        GLES20.glCompileShader(shader);
        int[] ok = new int[1];
        GLES20.glGetShaderiv(shader, GLES20.GL_COMPILE_STATUS, ok, 0);
        if (ok[0] == 0) {
            String log = GLES20.glGetShaderInfoLog(shader);
            GLES20.glDeleteShader(shader);
            throw new IllegalStateException("learned shader compile failed: " + log);
        }
        return shader;
    }

    private void allocate() {
        mipSize[0][0] = analysisWidth;
        mipSize[0][1] = analysisHeight;
        for (int k = 0; k < LEVELS; ++k) {
            if (k > 0) {
                mipSize[k][0] = (mipSize[k - 1][0] + 1) / 2;
                mipSize[k][1] = (mipSize[k - 1][1] + 1) / 2;
            }
            halfSize[k][0] = (mipSize[k][0] + 1) / 2;
            halfSize[k][1] = (mipSize[k][1] + 1) / 2;
            qSize[k][0] = (halfSize[k][0] + 1) / 2;
            qSize[k][1] = (halfSize[k][1] + 1) / 2;
        }
        for (int k = 0; k < LEVELS; ++k) {
            if (k > 0 || divisor > 1) mips[k] = texture(mipSize[k][0], mipSize[k][1], false);
            int hw = halfSize[k][0], hh = halfSize[k][1], qw = qSize[k][0], qh = qSize[k][1];
            for (int i = 0; i < 2; ++i) {
                e0[k][i] = texture(hw, hh, false);
                e1[k][i] = texture(hw, hh, false);
            }
            for (int i = 0; i < 4; ++i) {
                e2[k][i] = texture(qw, qh, false);
                for (int s = 0; s < SLOTS; ++s) features[s][k][i] = texture(qw, qh, false);
                scratchH[k][i] = texture(qw, qh, false);
                scratchG[k][i] = texture(qw, qh, false);
            }
            for (int i = 0; i < 3; ++i) corrTex[k][i] = texture(qw, qh, false);
            field1[k] = texture(qw, qh, true);
            if (k < DELTA_LEVELS) {
                field2[k] = texture(qw, qh, true);
                logits[k] = texture(qw, qh, true);
                for (int i = 0; i < 2; ++i) {
                    visV[k][i] = texture(qw, qh, false);
                    visU[k][i] = texture(qw, qh, false);
                }
            }
        }
        zeroField = texture(1, 1, true);
        forget();
    }

    private final java.util.List<Integer> owned = new java.util.ArrayList<>();

    private int texture(int width, int height, boolean half) {
        int[] id = new int[1];
        GLES20.glGenTextures(1, id, 0);
        GLES20.glBindTexture(GLES20.GL_TEXTURE_2D, id[0]);
        if (half) {
            java.nio.ByteBuffer zeros = java.nio.ByteBuffer.allocateDirect(width * height * 8)
                    .order(java.nio.ByteOrder.nativeOrder());
            GLES30.glTexImage2D(GLES20.GL_TEXTURE_2D, 0, GLES30.GL_RGBA16F, width, height, 0,
                    GLES20.GL_RGBA, GLES30.GL_HALF_FLOAT, zeros);
        } else {
            GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D, 0, GLES20.GL_RGBA, width, height, 0,
                    GLES20.GL_RGBA, GLES20.GL_UNSIGNED_BYTE, null);
        }
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_MIN_FILTER, GLES20.GL_LINEAR);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_MAG_FILTER, GLES20.GL_LINEAR);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_WRAP_S, GLES20.GL_CLAMP_TO_EDGE);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_WRAP_T, GLES20.GL_CLAMP_TO_EDGE);
        owned.add(id[0]);
        return id[0];
    }

    private void releaseTextures() {
        if (!owned.isEmpty()) {
            int[] ids = new int[owned.size()];
            for (int i = 0; i < ids.length; ++i) ids[i] = owned.get(i);
            GLES20.glDeleteTextures(ids.length, ids, 0);
            owned.clear();
        }
        verifiedTargets.clear();
        ready = false;
    }

    void release() {
        releaseTextures();
        int[] programs = {resample2, resample4, mip, enc0, enc1, enc2, enc3, corr,
                headC1[0], headC2[0], headC3[0], headOut[0], headC1[1], headC2[1], headC3[1], headOut[1],
                vis0, vis1, vis2, vis3, visOut, generate};
        for (int program : programs) if (program != 0) GLES20.glDeleteProgram(program);
        resample2 = resample4 = mip = enc0 = enc1 = enc2 = enc3 = corr = 0;
        java.util.Arrays.fill(headC1, 0); java.util.Arrays.fill(headC2, 0);
        java.util.Arrays.fill(headC3, 0); java.util.Arrays.fill(headOut, 0);
        vis0 = vis1 = vis2 = vis3 = visOut = generate = 0;
        uniforms.clear();
        if (framebuffer != 0) GLES20.glDeleteFramebuffers(1, new int[] {framebuffer}, 0);
        framebuffer = 0;
        attached = 0;
    }
}
